{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For a k-month contract signed at the start of the period, does it provide the full required area for each of months 1 through k (i.e., it covers the requirement in every month it spans), so that the monthly requirement is met by the sum of all active contracts that month?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the coverage logic for contracts across months."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "does that mean the total rented area in each month must be exactly equal to the required area (equality), or at least the required area (inequality, allowing surplus)?"
  ],
  "rationale": "The response asks for a single policy choice between equality and inequality constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The 4-month contract excludes the 1-month contract — does this mean that if any 4-month contract is chosen, no 1-month contract of any size may be chosen at all, or does it only forbid choosing a 1-month contract in addition to a 4-month contract for the same warehouse?"
  ],
  "rationale": "The response presents a single clarification question asking for a specific policy interpretation regarding the scope of the exclusion between 4-month and 1-month contracts."
}

{
  "action": "question",
